## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;
  localparam int BIT_CLKS = 40;  // prescale 5 * 8 clocks per bit

  logic clk = 1'b0;
  logic rst = 1'b1;
  logic rxd = 1'b1;
  logic m_axis_tready = 1'b1;
  logic [15:0] prescale = 16'd5;

  wire [7:0] m_axis_tdata;
  wire m_axis_tvalid;
  wire busy;
  wire overrun_error;
  wire frame_error;

  always #4 clk = ~clk;

  uart_rx dut (
    .clk(clk),
    .rst(rst),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .busy(busy),
    .overrun_error(overrun_error),
    .frame_error(frame_error),
    .prescale(prescale)
  );

  task automatic drive_bit(input logic value);
    rxd = value;
    repeat (BIT_CLKS) @(negedge clk);
  endtask

  task automatic send_frame(input logic [7:0] data,
                            input logic stop_value);
    drive_bit(1'b0);
    for (int i = 0; i < 8; i++)
      drive_bit(data[i]);
    drive_bit(stop_value);
  endtask

  initial begin
    repeat (4) @(negedge clk);
    rst = 1'b0;
    repeat (6) @(negedge clk);

    // A low stop bit produces a frame_error pulse. Return the line high
    // afterward and allow the receiver to settle into a long idle interval.
    send_frame(8'h5A, 1'b0);
    rxd = 1'b1;
    repeat (100) @(negedge clk);

    // The next frame delivers A5 after the idle interval.
    send_frame(8'hA5, 1'b1);
    repeat (100) @(negedge clk);

    $finish;
  end
endmodule
```

